import '../../../../Core/Models/product_model.dart';class ProductPreviewEntities extends ProductModel {  final String image;  ProductPreviewEntities({    required super.id,    required this.image,    required super.name,    required super.price,    required super.discountPrice,  }) : super(    slug: '',    categoryId: 0,    description: '',    additionalInfo: '',    dimensions: '',    featured: 0,    popular: 0,    status: 0,    quantity: 0,    createdAt: null,    updatedAt: null,    primaryImage: PrimaryImage(      id: 0,      productId: id,      image: image,      isPrimary: 1,      createdAt: null,      updatedAt: null,    ),    category: null,  );  factory ProductPreviewEntities.fromProduct(ProductModel product) {    return ProductPreviewEntities(      id: product.id,      image: product.primaryImage?.image ?? "",      name: product.name,      price: product.price,      discountPrice: product.discountPrice,    );  }  Map<String, dynamic> toMap() {    return {      'id': id,      'name': name,      'price': price,      'discountPrice': discountPrice,      'image': primaryImage?.image ?? '',    };  }}